import React, { useState } from 'react';

// Create the App component here
const App = () => {
  // Initialize your Redux-like state object here
  const initialState = { count: 0 };

  // Create reducer function here
  const reducer = (state, action) => {
    switch (action.type) {
      case 'INCREMENT':
        return { count: state.count + 1 };
      default:
        return state;
    }
  };

  // Use useState hook here
  const [state, setState] = useState(initialState);

  // Create dispatch function here
  const dispatch = (action) => {
    const newState = reducer(state, action);
    setState(newState);
  };

  return (
    <div style={{ padding: '20px' }}>
      <h1>Mini Redux Counter</h1>
      <p>Current count: {state.count}</p>
      <button onClick={() => dispatch({ type: 'INCREMENT' })}>
        Increment
      </button>
      {/* Add Decrement button here */}
    </div>
  );
};
